import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_TRAYECTO, MODELO_ESTACION, TABLA_TRAYECTOS } from '../../models/estacion-trayecto.model.mjs';

export async function buscarEstacionRepository(estacionId) {
  const { Item } = await MODELO_ESTACION.build(GetItemCommand)
    .key({ estacionId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarEstacionRepository(estacionId, minimo) {
  const { Items = [] } = await TABLA_TRAYECTOS.build(QueryCommand)
    .entities(MODELO_TRAYECTO)
    .query({ index: 'PorEstacion', partition: estacionId })
    .options({ filters: { Trayecto: { attr: 'distanciaKm', gte: minimo } } })
    .send();
  return Items;
}
